    mut pending: ResMut<DelayedCommandAcks>,
    mut senders: Query<&mut MessageSender<CommandAck>>,
    mut traffic: ResMut<ReliableTraffic>,
) {
    for (entity, ack) in std::mem::take(&mut pending.0) {
        if let Ok(mut sender) = senders.get_mut(entity) {
